class Solution {
public:
    bool isAdditiveNumber(string num) {
        int n = num.size();
        for (int i = 1; i <= n - 2; i++) {
            for (int j = 1; j <= n - i - 1; j++) {
                if (check(num, i, j)) return true;
            }
        }
        return false;
    }
private:
    bool check(const string& num, int i, int j) {
        int n = num.size();
        if (num[0] == '0' && i > 1) return false;
        if (num[i] == '0' && j > 1) return false;
        long long a = stoll(num.substr(0, i));
        long long b = stoll(num.substr(i, j));
        int pos = i + j;
        while (pos < n) {
            long long c = a + b;
            string cs = to_string(c);
            if (pos + (int)cs.size() > n) return false;
            if (num.compare(pos, cs.size(), cs) != 0) return false;
            pos += cs.size();
            a = b;
            b = c;
        }
        return true;
    }
};
